43	    /** 固定时钟：所有并发申请落在同一 UTC 日，预占均保持 RESERVED（不触发到期）。 */
44	    static class FixedClock extends Clock {
45	        private final Instant fixed;
46	
47	        FixedClock(Instant fixed) {
48	            this.fixed = fixed;
49	        }
