144	    @Test
145	    @DisplayName("同一预占并发确认/取消：只允许一个终态，额度不重复释放、不变负")
146	    void concurrentConfirmAndCancel_singleTerminal_noDoubleRelease() throws Exception {
147	        service.createCampaign(new CreateCampaignRequest("req-c", "cap", 1, 1));
148	        ReservationResponse r = service.apply(new ApplyExposureRequest("req-a", "cap", "v1"));
149	
150	        int threads = 24;
151	        ExecutorService pool = Executors.newFixedThreadPool(threads);
152	        CountDownLatch start = new CountDownLatch(1);
153	        AtomicInteger confirmed = new AtomicInteger();
154	        AtomicInteger cancelled = new AtomicInteger();
155	        AtomicInteger conflicts = new AtomicInteger();
156	
157	        for (int i = 0; i < threads; i++) {
158	            final boolean confirm = i % 2 == 0;
159	            final int idx = i;
160	            pool.submit(() -> {
161	                try {
162	                    start.await();
163	                    ReservationResponse result = confirm
164	                            ? service.confirm(r.reservationId(),
165	                                    new ReservationActionRequest("req-t-" + idx))
166	                            : service.cancel(r.reservationId(),
167	                                    new ReservationActionRequest("req-t-" + idx));
168	                    if (result.status().name().equals("CONFIRMED")) {
169	                        confirmed.incrementAndGet();
170	                    } else {
171	                        cancelled.incrementAndGet();
172	                    }
173	                } catch (ApiException ex) {
174	                    if (ex.getStatus().value() == 409) {
175	                        conflicts.incrementAndGet();
176	                    } else {
177	                        throw ex;
178	                    }
179	                } catch (InterruptedException e) {
180	                    Thread.currentThread().interrupt();
181	                }
182	            });
183	        }
184	        start.countDown();
185	        pool.shutdown();
186	        assertTrue(pool.awaitTermination(30, TimeUnit.SECONDS), "并发任务应在超时前完成");
187	
188	        // 确认与取消各 12 个线程；胜出方向的同向后继操作返回原状态，异向全部 409
189	        assertTrue(confirmed.get() == 0 || cancelled.get() == 0,
190	                "只允许存在一种终态，实际 confirmed=" + confirmed.get() + " cancelled=" + cancelled.get());
191	        assertEquals(12, confirmed.get() + cancelled.get(), "胜出方向的所有调用返回同一终态");
192	        assertEquals(12, conflicts.get(), "异向操作必须全部为 409");
193	
194	        ReservationResponse detail = service.getReservation(r.reservationId());
195	        int usedTotal = jdbc.queryForObject(
196	                "SELECT used_total FROM quota_total_ledger WHERE campaign_id = 'cap' AND utc_date = ?",
197	                Integer.class, java.sql.Date.valueOf(DAY));
198	        int usedVisitor = jdbc.queryForObject(
199	                "SELECT used_visitor FROM quota_visitor_ledger "
200	                        + "WHERE campaign_id = 'cap' AND visitor_id = 'v1' AND utc_date = ?",
201	                Integer.class, java.sql.Date.valueOf(DAY));
202	        assertTrue(usedTotal >= 0 && usedVisitor >= 0, "账目不得为负");
203	        if (detail.status().name().equals("CANCELLED")) {
204	            assertEquals(0, usedTotal, "取消后总额度应恰好释放一次");
205	            assertEquals(0, usedVisitor, "取消后访客额度应恰好释放一次");
206	        } else {
